CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','consulta') NOT NULL DEFAULT 'admin',active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE modules (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,module_key VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,enabled TINYINT(1) NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE permissions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,permission_key VARCHAR(100) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL,module_key VARCHAR(60) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE role_permissions (role_name VARCHAR(60) NOT NULL,permission_id INT UNSIGNED NOT NULL,PRIMARY KEY(role_name,permission_id),FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE settings (setting_key VARCHAR(120) PRIMARY KEY,setting_value TEXT NULL,is_secret TINYINT(1) NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE document_sequences (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,document_type VARCHAR(60) NOT NULL,year_no SMALLINT UNSIGNED NOT NULL,next_number INT UNSIGNED NOT NULL DEFAULT 1,prefix VARCHAR(20),UNIQUE KEY(document_type,year_no)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NULL,module_key VARCHAR(60) NOT NULL,action VARCHAR(80) NOT NULL,entity_type VARCHAR(80),entity_id VARCHAR(80),before_data JSON NULL,after_data JSON NULL,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(module_key,created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE clients (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_name VARCHAR(180) NOT NULL,contact_name VARCHAR(150),cuit VARCHAR(20),iva_condition VARCHAR(60),email VARCHAR(190),whatsapp VARCHAR(50),address VARCHAR(255),city VARCHAR(120),province VARCHAR(120),country VARCHAR(120) NOT NULL DEFAULT 'Argentina',notes TEXT,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE project_partners (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,partner_type ENUM('arquitecto','estudio_arquitectura','constructora','desarrolladora','otro') NOT NULL DEFAULT 'arquitecto',business_name VARCHAR(180) NOT NULL,contact_name VARCHAR(150),cuit VARCHAR(20),email VARCHAR(190),whatsapp VARCHAR(50),address VARCHAR(255),city VARCHAR(120),province VARCHAR(120),country VARCHAR(120) NOT NULL DEFAULT 'Argentina',notes TEXT,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE projects (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,client_id INT UNSIGNED NOT NULL,partner_id INT UNSIGNED NULL,project_number VARCHAR(50) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,status ENUM('consulta','presupuestado','aprobado','en_obra','finalizado','cancelado') NOT NULL DEFAULT 'consulta',currency ENUM('ARS','USD') NOT NULL DEFAULT 'ARS',tax_mode ENUM('sin_iva','iva_incluido','mas_iva') NOT NULL DEFAULT 'sin_iva',vat_rate DECIMAL(5,2) NOT NULL DEFAULT 21,engineering_pct DECIMAL(5,2) NOT NULL DEFAULT 10,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(client_id) REFERENCES clients(id),FOREIGN KEY(partner_id) REFERENCES project_partners(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE quotes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id INT UNSIGNED NOT NULL,version_no INT UNSIGNED NOT NULL,quote_category ENUM('general','domotica','redes','camaras','alarma','audio') NOT NULL DEFAULT 'general',quote_date DATE NOT NULL,materials_amount DECIMAL(15,2) NOT NULL DEFAULT 0,labor_amount DECIMAL(15,2) NOT NULL DEFAULT 0,subtotal DECIMAL(15,2) NOT NULL,tax_mode ENUM('sin_iva','iva_incluido','mas_iva') NOT NULL,vat_rate DECIMAL(5,2) NOT NULL DEFAULT 21,total DECIMAL(15,2) NOT NULL,status ENUM('borrador','enviado','aprobado_inicial','final','rechazado') NOT NULL DEFAULT 'borrador',file_path VARCHAR(255),notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(project_id,version_no),INDEX(project_id,quote_category),FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE charges (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id INT UNSIGNED NOT NULL,quote_id INT UNSIGNED NULL,charge_date DATE NOT NULL,type ENUM('ingenieria','materiales','mano_obra','adicional','ajuste') NOT NULL,description VARCHAR(255) NOT NULL,amount DECIMAL(15,2) NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,FOREIGN KEY(quote_id) REFERENCES quotes(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE payments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id INT UNSIGNED NOT NULL,payment_date DATE NOT NULL,amount DECIMAL(15,2) NOT NULL,method ENUM('transferencia','efectivo','cheque','tarjeta','otro') NOT NULL DEFAULT 'transferencia',reference VARCHAR(150),notes TEXT,receipt_path VARCHAR(255),receipt_number VARCHAR(40) UNIQUE,public_token VARCHAR(64) UNIQUE,email_sent_at DATETIME NULL,whatsapp_opened_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE allocations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,payment_id INT UNSIGNED NOT NULL,charge_id INT UNSIGNED NOT NULL,amount DECIMAL(15,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(payment_id,charge_id),FOREIGN KEY(payment_id) REFERENCES payments(id) ON DELETE CASCADE,FOREIGN KEY(charge_id) REFERENCES charges(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO modules(module_key,name,enabled,sort_order) VALUES ('accounts','Cuentas por cobrar',1,10),('crm','Clientes y CRM',0,20),('projects','Gestión de proyectos',0,30),('quotes','Presupuestos',0,40),('arca','Facturación ARCA',0,50),('purchases','Compras y proveedores',0,60),('inventory','Stock y materiales',0,70),('treasury','Tesorería y bancos',0,80);
INSERT INTO permissions(permission_key,name,module_key) VALUES ('accounts.view','Ver cuentas por cobrar','accounts'),('accounts.manage','Administrar cuentas por cobrar','accounts'),('clients.manage','Administrar clientes','crm'),('projects.manage','Administrar proyectos','projects'),('settings.manage','Administrar configuración','core');
